/* NEU Global Opportunities — lightweight, accessible browser interface.
   Maintains project branding and four official categories. */
'use strict';
const CATEGORIES=[
 {id:'Academic Internationalization',short:'Academic',icon:'🎓',accent:'accent-academic',color:'#a69be8'},
 {id:'Research Internationalization',short:'Research',icon:'🔬',accent:'accent-research',color:'#70b8ac'},
 {id:'Business/Industry Internationalization',short:'Business & Industry',icon:'💼',accent:'accent-business',color:'#7fa9dc'},
 {id:'Community/MSME Internationalization',short:'Community / MSME',icon:'🌱',accent:'accent-msme',color:'#e9a67e'}
];
const COUNTRIES=['Philippines','Japan','South Korea','Singapore','Malaysia','Thailand'];
const PH_REGIONS=['Nationwide (All PH Regions)','National Capital Region (NCR)','Cordillera Administrative Region (CAR)','Region I (Ilocos Region)','Region II (Cagayan Valley)','Region III (Central Luzon)','Region IV-A (CALABARZON)','MIMAROPA Region','Region V (Bicol Region)','Region VI (Western Visayas)','Negros Island Region (NIR)','Region VII (Central Visayas)','Region VIII (Eastern Visayas)','Region IX (Zamboanga Peninsula)','Region X (Northern Mindanao)','Region XI (Davao Region)','Region XII (SOCCSKSARGEN)','Region XIII (Caraga)','Bangsamoro Autonomous Region in Muslim Mindanao (BARMM)'];
const FLAGS={'Philippines':'🇵🇭','Japan':'🇯🇵','South Korea':'🇰🇷','Singapore':'🇸🇬','Malaysia':'🇲🇾','Thailand':'🇹🇭'};
const STAKEHOLDERS=['Students','Faculty & Researchers','MSMEs & Entrepreneurs','University Administrators'];
const STATUS_OPTIONS=['OPEN','CLOSED','CHECK CURRENT INTAKE','ONGOING PROGRAM','UPCOMING'];
const state={me:null,opportunities:[],settings:NEU_DEFAULT_SETTINGS,users:[],requests:[],bookmarks:[],revisions:[],reports:[],feedback:[],activity:[],page:'overview',tab:CATEGORIES[0].id,query:'',country:'',region:'',sort:'recent',compare:[],onlySaved:false,manageTab:'records',manageQuery:'',includeArchived:false,working:false,authMode:'login',pendingEmail:'',authRecovery:false};
const $=s=>document.querySelector(s);
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate=s=>s?new Date(s.slice(0,10)+'T00:00:00').toLocaleDateString('en-PH',{year:'numeric',month:'short',day:'numeric'}):'Not specified';
const clip=(s,n=115)=>String(s||'').length>n?String(s).slice(0,n-1)+'…':String(s||'');
const cat=s=>CATEGORIES.find(x=>x.id===s)||CATEGORIES[0];
const roleAtLeast=role=>({student:0,staff:1,admin:2}[state.me?.role]??-1)>=({student:0,staff:1,admin:2}[role]??0);
const published=()=>state.opportunities.filter(o=>o.verification==='VERIFIED'&&!o.archived);
const opp=id=>state.opportunities.find(o=>o.id===id);
const saved=id=>state.bookmarks.some(x=>x.opportunity_id===id);
const locationLabel=o=>o.country==='Philippines'?`${o.region||'Region unspecified'}, Philippines`:o.country;
const scoreLabel=o=>o.score===null?'Not assessed':`${Number(o.score).toFixed(1)}/100`;
const deadlineState=o=>{if(!o.deadline)return 'none';const days=Math.ceil((new Date(o.deadline+'T00:00:00')-new Date(new Date().toDateString()))/86400000);return days<0?'expired':days<=14?'soon':'normal';};
const statusChip=(text,tone='neutral')=>`<span class="status-chip ${tone}">${escapeHTML(text)}</span>`;
const categoryTag=s=>`<span class="category-tag ${cat(s).accent}">${cat(s).icon} ${escapeHTML(cat(s).short)}</span>`;
const scoreHTML=o=>o.score===null?'<span class="score-big na">Not assessed</span>':`<span class="score-big small">${Number(o.score).toFixed(1)}<small style="font-size:11px;color:#8992a4">/100</small></span>`;
const stateChip=o=>o.priority==='NOT ASSESSED'?statusChip('Evidence incomplete','neutral'):statusChip(`${o.priority.toLowerCase()} priority`,o.priority==='HIGH'?'good':o.priority==='MEDIUM'?'warn':'neutral');
const appChip=o=>{const d=deadlineState(o);const closed=/CLOSED|EXPIRED/i.test(o.application_status||'')||d==='expired';return statusChip(closed?'Application closed':(o.application_status||'Check latest intake'),closed?'bad':d==='soon'?'warn':'neutral');};
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='toast'+(error?' error':'');clearTimeout(toast._t);toast._t=setTimeout(()=>el.classList.add('hidden'),4600);}
function showModal(content,wide=false){$('#modal').innerHTML=content;$('#modal').classList.toggle('wide-modal',wide);$('#modal').classList.remove('hidden');$('#overlay').classList.remove('hidden');$('#modal').scrollTop=0;}
function closeModal(){$('#overlay').classList.add('hidden');$('#modal').classList.add('hidden');$('#modal').innerHTML='';}
function modalHeader(title,sub=''){return `<div class="dialog-head"><div><span class="eyebrow">GLOBAL OPPORTUNITIES</span><h2>${escapeHTML(title)}</h2>${sub?`<p class="muted small">${escapeHTML(sub)}</p>`:''}</div><button class="icon-button" type="button" data-action="close-modal" aria-label="Close dialog">×</button></div>`;}
function field(name,label,val='',type='text',required=false,extra=''){return `<div class="form-input"><label for="f-${name}">${escapeHTML(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${escapeHTML(val)}" ${required?'required':''} ${extra}></div>`;}
function area(name,label,val='',required=false){return `<div class="form-input wide"><label for="f-${name}">${escapeHTML(label)}</label><textarea id="f-${name}" name="${name}" rows="3" ${required?'required':''}>${escapeHTML(val)}</textarea></div>`;}
function select(name,label,choices,val='',required=false){return `<div class="form-input"><label for="f-${name}">${escapeHTML(label)}</label><select id="f-${name}" name="${name}" ${required?'required':''}>${choices.map(item=>{const [value,text]=Array.isArray(item)?item:[item,item];return `<option value="${escapeHTML(value)}" ${value===val?'selected':''}>${escapeHTML(text)}</option>`;}).join('')}</select></div>`;}
function needLogin(){showLogin();toast('Sign in to access GOID.',true);}
const GOID_YEARS=['1st Year','2nd Year','3rd Year','4th Year','5th Year','Graduate / Postgraduate','Other'];
function renderAuth(mode='login'){
 state.authMode=mode;const x=$('#auth-view');if(!x)return;
 if(mode==='signup')x.innerHTML=`<h2 class="auth-title">Join GOID ✨</h2><p class="auth-subtitle">Create your account to explore opportunities, save items, and ask for guidance.</p><form id="signup-form" class="login-form"><div class="registration-grid"><label>Full name<input name="full_name" autocomplete="name" maxlength="120" placeholder="Full name" required></label><label>College / Department<input name="college" autocomplete="organization" maxlength="120" placeholder="Your college" required></label></div><div class="registration-grid"><label>Year level<select name="year_level" required><option value="">Choose year level</option>${GOID_YEARS.map(y=>`<option>${escapeHTML(y)}</option>`).join('')}</select></label><label>Email address<input type="email" name="email" autocomplete="email" placeholder="Your email" required></label></div><div class="registration-grid"><label>Contact number <span class="muted tiny">(optional)</span><input name="contact_number" type="tel" maxlength="30" placeholder="09..." autocomplete="tel"></label><label>Telegram <span class="muted tiny">(optional)</span><input name="telegram_username" maxlength="50" placeholder="@username"></label></div><div class="registration-grid"><label>Password<input name="password" type="password" minlength="10" autocomplete="new-password" placeholder="At least 10 characters" required></label><label>Confirm password<input name="confirm_password" type="password" minlength="10" autocomplete="new-password" required></label></div><label class="privacy-check"><input type="checkbox" name="privacy_acknowledged" required><span>I have read the privacy notice. GOID stores my registration details to provide account access and assistance. Contact information is visible only to authorized personnel handling my requests. <a href="#" data-action="privacy" style="color:#6760b4">Read privacy notice</a>.</span></label><button type="submit" class="btn primary full">Create account →</button></form><div class="auth-links"><button class="auth-link" data-action="auth-login" type="button">Already registered? Sign in</button></div>`;
 else if(mode==='verify')x.innerHTML=`<h2 class="auth-title">Check your inbox ✉</h2><p class="auth-subtitle">If the address can be registered, a verification email will be sent to <b>${escapeHTML(state.pendingEmail||'your email')}</b>. Open the link, then sign in.</p><div class="auth-prompt">If you can't find the email, check Spam or Junk. Email delivery requires a configured SMTP provider.</div><form id="resend-form" class="login-form"><label>Email address<input type="email" name="email" required value="${escapeHTML(state.pendingEmail||'')}"></label><button class="btn soft full" type="submit">Resend verification email</button></form><button class="auth-link" type="button" data-action="auth-login">Return to sign in</button>`;
 else if(mode==='reset-sent')x.innerHTML=`<h2 class="auth-title">Check your email ✉</h2><p class="auth-subtitle">If an account exists for <b>${escapeHTML(state.pendingEmail||'that address')}</b>, a password-reset link has been sent. Check your inbox and Spam folder.</p><button class="auth-link" type="button" data-action="auth-login">Return to sign in</button>`;
 else if(mode==='forgot')x.innerHTML=`<h2 class="auth-title">Reset password 🔐</h2><p class="auth-subtitle">Enter your registered email to request a password-reset link.</p><form id="forgot-form" class="login-form"><label>Email address<input name="email" type="email" autocomplete="email" required></label><button class="btn primary full" type="submit">Send password reset</button></form><button class="auth-link" type="button" data-action="auth-login">Back to sign in</button>`;
 else if(mode==='new-password')x.innerHTML=`<h2 class="auth-title">Choose a new password</h2><p class="auth-subtitle">Use at least 10 characters.</p><form id="new-password-form" class="login-form"><label>New password<input name="password" type="password" minlength="10" autocomplete="new-password" required></label><label>Confirm password<input name="confirm_password" type="password" minlength="10" autocomplete="new-password" required></label><button class="btn primary full" type="submit">Update password</button></form>`;
 else x.innerHTML=`<h2 class="auth-title">Welcome to GOID 👋</h2><p class="auth-subtitle">Your opportunities, all in one place. Sign in with your email and password.</p><form id="login-form" class="login-form"><label>Email address<input type="email" name="email" autocomplete="email" placeholder="you@example.com" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button type="submit" class="btn primary full">Log in →</button></form><div class="auth-links"><button type="button" class="auth-link" data-action="auth-signup">Create an account</button><button type="button" class="auth-link" data-action="auth-forgot">Forgot password?</button></div>`;
}
function showLogin(mode='login'){$('#login-screen').classList.remove('hidden');$('#shell').classList.add('hidden');document.body.removeAttribute('data-role');renderAuth(mode);window.scrollTo(0,0);}
function shellUser(){
 const me=state.me;if(!me)return showLogin();
 $('#login-screen').classList.add('hidden');$('#shell').classList.remove('hidden');document.body.dataset.role=me.role;
 $('#user-display').textContent=me.display_name||me.email||'GOID user';$('#user-role').textContent={student:'Student',staff:'Staff',admin:'Admin'}[me.role]||'Account';
 $('#user-avatar').textContent=(me.display_name||'G')[0].toUpperCase();$('#top-avatar').textContent=(me.display_name||'G')[0].toUpperCase();
 $('#auth-button').dataset.action='logout';$('#auth-button').title='Sign out';$('#auth-button').textContent='↪';
}
async function boot(refresh=false){
 if(state.working)return;state.working=true;
 try{
  const result=await neuApi('/api/bootstrap');const oldUser=state.me?.id;
  Object.assign(state,{me:result.me,opportunities:result.opportunities,settings:result.settings,users:result.users,requests:result.requests,bookmarks:result.bookmarks,revisions:result.revisions,reports:result.reports,feedback:result.feedback,activity:result.activity});
  if(!result.authenticated||!state.me){showLogin(state.authRecovery?'new-password':'login');return;}
  if(oldUser!==state.me?.id){state.compare=[];state.page='overview';}
  if(!roleAtLeast('staff')&&['manage','settings'].includes(state.page))state.page='overview';
  if(!roleAtLeast('student')&&['saved','requests'].includes(state.page))state.page='overview';
  if(state.authRecovery){showLogin('new-password');return;}
  shellUser();navigation();if(!refresh||$('#modal').classList.contains('hidden'))render();
 }catch(e){if(!refresh){showLogin();$('#config-status').textContent='Setup error: '+e.message;}toast(e.message,true);console.warn(e);}finally{state.working=false;}
}
function navigation(){const pages=[['overview','⌂','Overview'],['explore','◈','Explore opportunities'],['compare','▣','Compare'],['insights','◫','Insights']];
 if(roleAtLeast('student'))pages.push(['saved','♡','Saved opportunities'],['requests','✉','My assistance'],['profile','♙','My profile']);
 if(roleAtLeast('staff'))pages.push(['manage','✎','Manage records']);
 if(roleAtLeast('admin'))pages.push(['settings','⚙','Settings & users']);
 if(roleAtLeast('student'))pages.push(['feedback','✧','Share feedback']);
 $('#primary-nav').innerHTML=pages.map(([id,icon,name])=>`<button class="nav-link ${id===state.page?'active':''}" data-action="nav" data-page="${id}"><span class="nav-ico">${icon}</span>${name}</button>`).join('');
 $('#page-name').textContent=pages.find(x=>x[0]===state.page)?.[2]||'Overview';
}
function navigate(page){state.page=page;state.query='';state.country='';state.region='';state.tab=CATEGORIES[0].id;state.sort='recent';navigation();render();$('#sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'instant'});}
function heading(kicker,title,description,actions=''){return `<div class="page-header"><div><span class="eyebrow">${escapeHTML(kicker)}</span><h1>${escapeHTML(title)}</h1><p>${escapeHTML(description)}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`;}
function render(){const v=$('#app-view');v.innerHTML=({overview:renderOverview,explore:renderExplore,compare:renderCompare,insights:renderInsights,saved:renderSaved,requests:renderRequests,manage:renderManage,settings:renderSettings,feedback:renderFeedback,profile:renderProfile}[state.page]||renderOverview)();}
function opportunityCard(o){const c=cat(o.sector),days=deadlineState(o),deadline=o.deadline?`${fmtDate(o.deadline)}${days==='soon'?' · Soon':days==='expired'?' · Passed':''}`:'Check source';
 return `<article class="card-op ${c.accent}"><div class="card-op-top">${categoryTag(o.sector)}${appChip(o)}</div><div><h3>${escapeHTML(o.title)}</h3><p>📍 ${escapeHTML(locationLabel(o))} · ${escapeHTML(o.source_org||'Official source')}</p></div><p>${escapeHTML(clip(o.description,106))}</p><div class="info-strip"><span>🗓 ${escapeHTML(deadline)}</span>${stateChip(o)}</div><div class="card-op-footer">${scoreHTML(o)}<div class="card-actions">${roleAtLeast('student')?`<button type="button" class="btn sm light" aria-label="${saved(o.id)?'Remove saved opportunity':'Save opportunity'}" data-action="bookmark" data-id="${o.id}">${saved(o.id)?'♥':'♡'}</button>`:''}<button class="btn sm light" type="button" title="Add to compare" data-action="compare-add" data-id="${o.id}">⇄</button><button class="btn sm soft" type="button" data-action="detail" data-id="${o.id}">View details</button></div></div></article>`;}
function renderOverview(){const rows=published(),assessed=rows.filter(o=>o.score!==null),counts=CATEGORIES.map(x=>rows.filter(r=>r.sector===x.id).length),high=rows.filter(x=>x.priority==='HIGH').length,soon=rows.filter(o=>deadlineState(o)==='soon').length;
 const denominator=Math.max(1,rows.length),recent=[...rows].sort((a,b)=>(b.created_at||'').localeCompare(a.created_at||'')).slice(0,3);
 const countries=COUNTRIES.map(c=>({name:c,count:rows.filter(o=>o.country===c).length})),maxCount=Math.max(1,...countries.map(x=>x.count));
 return `<section class="hero"><div class="hero-copy"><span class="eyebrow">✦ NEU GLOBAL INTELLIGENCE CENTER</span><h1>A world of opportunities,<br>in one happy place.</h1><p>Source-linked opportunities across the Philippines and five Asian markets. Explore, compare, and choose your direction.</p><button class="btn primary" data-action="nav" data-page="explore">Explore opportunities →</button></div><div class="hero-art">🌏</div></section>
 <div class="metrics"><div class="metric"><div><div class="label">Published opportunities</div><div class="value">${rows.length}</div></div><div class="metric-icon">🌍</div></div><div class="metric"><div><div class="label">Evidence-assessed</div><div class="value">${assessed.length}</div></div><div class="metric-icon">⚖️</div></div><div class="metric"><div><div class="label">High priority*</div><div class="value">${high}</div></div><div class="metric-icon">✨</div></div><div class="metric"><div><div class="label">Deadlines within 14 days</div><div class="value">${soon}</div></div><div class="metric-icon">📅</div></div></div>
 <div class="section-heading"><h2>At a glance</h2><p>Charts recalculate from approved listings</p></div><div class="chart-duo"><section class="soft-panel"><h3>🧁 Opportunities by category</h3><p class="muted small">All four internationalization sectors</p><div class="bar-stack">${CATEGORIES.map((x,i)=>`<span class="bar-piece" style="width:${counts[i]/denominator*100}%;background:${x.color}"></span>`).join('')}</div><div class="legend-list">${CATEGORIES.map((x,i)=>`<div class="legend-item"><span class="legend-name"><i class="category-dot" style="background:${x.color}"></i>${escapeHTML(x.short)}</span><b>${counts[i]}</b></div>`).join('')}</div></section><section class="soft-panel"><h3>🌏 By location</h3><p class="muted small">Approved countries and Philippine opportunities</p>${countries.map(c=>`<div class="hbar"><div class="hbar-label"><span>${FLAGS[c.name]} ${escapeHTML(c.name)}</span><b>${c.count}</b></div><div class="hbar-track"><div class="hbar-fill" style="width:${c.count/maxCount*100}%"></div></div></div>`).join('')}</section></div>
 <div class="section-heading"><h2>Recently added</h2><button class="btn sm soft" data-action="nav" data-page="explore">View all →</button></div><div class="ui-grid">${recent.length?recent.map(opportunityCard).join(''):'<div class="empty"><strong>No published listings yet</strong>Staff can submit opportunities for Admin verification.</div>'}</div>
 <p class="muted small" style="margin-top:18px">*Priority is a student-project rubric, not a university rating. A listing without sufficient evidence is not scored. Application availability must be confirmed on the official source.</p>`;
}
function explored(){let rows=published().filter(o=>o.sector===state.tab);if(state.query){const q=state.query.toLowerCase();rows=rows.filter(o=>(o.title+' '+o.description+' '+o.source_org+' '+o.country+' '+o.region).toLowerCase().includes(q));}if(state.country)rows=rows.filter(o=>o.country===state.country);if(state.region)rows=rows.filter(o=>o.region===state.region);
 if(state.sort==='score')rows.sort((a,b)=>(b.score??-1)-(a.score??-1));if(state.sort==='deadline')rows.sort((a,b)=>(a.deadline||'9999').localeCompare(b.deadline||'9999'));if(state.sort==='recent')rows.sort((a,b)=>(b.created_at||'').localeCompare(a.created_at||''));return rows;}
function renderExplore(){return heading('DISCOVER','Explore opportunities 🌏','Choose a category, then filter by location or keyword.')+
 `<div class="category-tabs">${CATEGORIES.map(c=>`<button class="category-tab ${c.accent} ${state.tab===c.id?'active':''}" data-action="category" data-sector="${escapeHTML(c.id)}" aria-pressed="${state.tab===c.id}">${c.icon} ${escapeHTML(c.short)}</button>`).join('')}</div><div class="filter-bar"><input id="query" aria-label="Search opportunities" placeholder="Search opportunities or organizations…" value="${escapeHTML(state.query)}"><select id="country" aria-label="Filter country"><option value="">All destinations</option>${COUNTRIES.map(c=>`<option value="${escapeHTML(c)}" ${state.country===c?'selected':''}>${escapeHTML(c)}</option>`).join('')}</select><select id="region" aria-label="Filter Philippine region" ${state.country!=='Philippines'?'disabled':''}><option value="">All PH regions</option>${PH_REGIONS.map(r=>`<option value="${escapeHTML(r)}" ${state.region===r?'selected':''}>${escapeHTML(r)}</option>`).join('')}</select><select id="sort" aria-label="Sort opportunities"><option value="recent" ${state.sort==='recent'?'selected':''}>Recently added</option><option value="score" ${state.sort==='score'?'selected':''}>Assessment score</option><option value="deadline" ${state.sort==='deadline'?'selected':''}>Deadline</option></select></div><p class="result-count" id="result-count" aria-live="polite"></p><div class="ui-grid" id="explore-list"></div>`;
}
function updateExplore(){const list=explored();$('#result-count').textContent=`${list.length} ${cat(state.tab).short} opportunit${list.length===1?'y':'ies'}`;$('#explore-list').innerHTML=list.length?list.map(opportunityCard).join(''):'<div class="empty"><strong>No matches in this category</strong>Try another location, keyword, or category.</div>';}
function renderCompare(){const rows=state.compare.map(opp).filter(o=>o&&o.verification==='VERIFIED'&&!o.archived),available=published().filter(o=>!rows.some(x=>x.id===o.id));return heading('COMPARE','Compare opportunities','Place up to three opportunities side by side. Incomplete evidence never becomes a fake score.',`<button class="btn soft" data-action="nav" data-page="explore">Explore opportunities</button>`)+
 `<div class="alert-banner purple">Comparisons are indicative. Different program types may have different benefits and eligibility requirements.</div><div class="filter-bar"><select id="compare-add"><option value="">Add an opportunity…</option>${available.map(o=>`<option value="${o.id}">${escapeHTML(clip(o.title,75))}</option>`).join('')}</select><button class="btn sm light" data-action="clear-compare">Clear selection</button><span class="muted small">${rows.length}/3 selected</span></div><div class="ui-grid" style="margin-top:15px">${rows.length?rows.map(o=>`<article class="soft-panel ${cat(o.sector).accent}" style="border-top:5px solid var(--cat)"><div class="card-op-top">${categoryTag(o.sector)}${stateChip(o)}</div><h3 style="margin-top:12px">${escapeHTML(o.title)}</h3><p class="muted small">${escapeHTML(locationLabel(o))}</p><div style="margin:16px 0">${scoreHTML(o)}</div><div class="detail-item"><b>Funding/support</b><p>${escapeHTML(clip(o.funding,150)||'Check official source')}</p></div><div class="detail-item" style="margin:9px 0"><b>Eligibility</b><p>${escapeHTML(clip(o.eligibility,150)||'See official requirements')}</p></div><div class="detail-item"><b>Deadline</b><p>${fmtDate(o.deadline)}</p></div><div class="card-op-footer" style="margin-top:18px"><button class="btn sm soft" data-action="detail" data-id="${o.id}">Details</button><button class="btn sm light" data-action="compare-remove" data-id="${o.id}">Remove</button></div></article>`).join(''):'<div class="empty"><strong>No opportunities selected</strong>Choose up to three using the dropdown or Explore page.</div>'}</div>`;}
function renderInsights(){const rows=published(),rank=[...rows].sort((a,b)=>(b.score??-1)-(a.score??-1)),assessed=rank.filter(o=>o.score!==null),unscored=rank.filter(o=>o.score===null);return heading('ANALYZE','Opportunity insights ✨','Source-linked listings with transparent, evidence-based assessments.')+
 `<div class="alert-banner purple">Scores are calculated from source-backed rubric selections. The weights and classifications are proposed by the research team and remain open to faculty validation. Missing evidence means <b>Not assessed</b>.</div><div class="chart-duo"><section class="soft-panel"><h3>Assessment completeness</h3><div class="bar-stack"><span class="bar-piece" style="width:${assessed.length/Math.max(1,rows.length)*100}%;background:#70b8ac"></span><span class="bar-piece" style="width:${unscored.length/Math.max(1,rows.length)*100}%;background:#e4e4f0"></span></div><div class="legend-item"><span>Evidence-assessed</span><b>${assessed.length}</b></div><div class="legend-item"><span>Not yet assessed</span><b>${unscored.length}</b></div></section><section class="soft-panel"><h3>Priority distribution</h3>${['HIGH','MEDIUM','LOW'].map((x,i)=>`<div class="hbar"><div class="hbar-label"><span>${x.charAt(0)+x.slice(1).toLowerCase()} priority</span><b>${rows.filter(o=>o.priority===x).length}</b></div><div class="hbar-track"><div class="hbar-fill" style="background:${['#70b8ac','#e9bd77','#9ba6c9'][i]};width:${rows.filter(o=>o.priority===x).length/Math.max(1,rows.length)*100}%"></div></div></div>`).join('')}</section></div><div class="section-heading"><h2>Opportunity rankings</h2><p>Unassessed listings shown last</p></div><div class="rank-list">${rank.length?rank.map((o,i)=>`<div class="rank-item ${cat(o.sector).accent}"><span class="position">${i+1}</span><i class="category-line"></i><div class="rank-main"><b>${escapeHTML(o.title)}</b><small>${cat(o.sector).icon} ${escapeHTML(cat(o.sector).short)} · ${escapeHTML(locationLabel(o))}</small></div>${scoreHTML(o)}<button class="btn sm soft" data-action="detail" data-id="${o.id}">Details</button></div>`).join(''):'<div class="empty">No published opportunities yet.</div>'}</div>`;}
function renderSaved(){const rows=published().filter(o=>saved(o.id));return heading('MY LIST','Saved opportunities ♡','Private to your account. Your saves do not influence opportunity rankings.')+`<div class="ui-grid">${rows.length?rows.map(opportunityCard).join(''):'<div class="empty"><strong>No saved opportunities yet</strong>Tap ♡ on any opportunity to keep it here.</div>'}</div>`;}
function renderRequests(){const rows=state.requests.filter(x=>x.requester_id===state.me.id);return heading('MY INQUIRIES','My assistance requests ✉','Track your requests and check replies from authorized project Staff.')+`<div class="ui-grid two">${rows.length?rows.map(r=>`<section class="soft-panel"><div class="card-op-top">${statusChip(r.status,r.status==='RESOLVED'?'good':r.status==='IN PROGRESS'?'warn':'neutral')}<span class="muted tiny">${fmtDate(r.created_at)}</span></div><h3>${escapeHTML(opp(r.opportunity_id)?.title||'Opportunity')}</h3><p class="muted small">${escapeHTML(r.help_type)}</p><p style="font-size:12px;white-space:pre-wrap">${escapeHTML(r.message||'No additional message')}</p>${r.staff_reply?`<div class="alert-banner teal"><b>Staff reply:</b><p style="margin:6px 0 0;white-space:pre-wrap">${escapeHTML(r.staff_reply)}</p></div>`:''}</section>`).join(''):'<div class="empty"><strong>No requests yet</strong>Open an opportunity to request application guidance.</div>'}</div><p class="muted small" style="margin-top:14px">This is a proposed academic assistance workflow, not a guaranteed official university support service.</p>`;}
function renderManage(){if(!roleAtLeast('staff'))return '';
 const tabs=[['records','Opportunities'],['revisions',`Proposed edits (${state.revisions.filter(r=>r.status==='PENDING').length})`],['assistance',`Assistance (${state.requests.filter(r=>r.status!=='RESOLVED').length})`],['reports',`Reports (${state.reports.filter(r=>r.status==='OPEN').length})`],['feedback','Feedback']];
 return heading('STAFF WORKSPACE','Manage opportunities ✎','Review submissions, maintain source information, and respond to requests.',`<button class="btn primary" data-action="add">+ Add opportunity</button>`)+
 `<div class="workflow-tabs">${tabs.map(([id,name])=>`<button class="workflow-tab ${state.manageTab===id?'active':''}" data-action="manage-tab" data-tab="${id}">${escapeHTML(name)}</button>`).join('')}</div><div id="manage-content">${renderManageTab()}</div>`;
}
function renderManageTab(){if(state.manageTab==='records'){
 const rows=state.opportunities.filter(o=>(state.includeArchived||!o.archived)&&(!state.manageQuery||(o.title+' '+o.country+' '+o.source_org).toLowerCase().includes(state.manageQuery.toLowerCase())));
 return `<div class="alert-banner purple">New listings require Admin source review. Staff edits to approved listings are submitted as <b>pending changes</b>; Students continue seeing the original record until approval.</div><div class="filter-bar"><input id="manage-query" placeholder="Search managed records" value="${escapeHTML(state.manageQuery)}"><button class="btn sm soft" data-action="export">Export JSON</button><button class="btn sm light" data-action="export-csv">Export CSV</button><button class="btn sm light" data-action="show-archived">${state.includeArchived?'Hide archived':'Show archived'}</button><button class="btn sm light" data-action="import">Import pending JSON</button></div><div class="data-table-wrap" style="margin-top:12px"><table><thead><tr><th>Opportunity</th><th>Category</th><th>Verification</th><th>Assessment</th><th>Actions</th></tr></thead><tbody>${rows.length?rows.map(o=>`<tr><td><strong>${escapeHTML(clip(o.title,54))}</strong><small class="table-sub">${escapeHTML(locationLabel(o))}</small></td><td>${categoryTag(o.sector)}</td><td>${statusChip(o.verification,o.verification==='VERIFIED'?'good':'warn')}</td><td>${scoreHTML(o)}</td><td><div class="table-actions"><button class="btn sm soft" data-action="edit" data-id="${o.id}">${o.verification==='VERIFIED'&&!roleAtLeast('admin')?'Propose edit':'Edit'}</button>${roleAtLeast('admin')&&o.verification==='PENDING VERIFICATION'?`<button class="btn sm primary" data-action="approve" data-id="${o.id}">Review</button>`:''}${roleAtLeast('admin')?`<button class="btn sm light" data-action="${o.archived?'restore':'archive'}" data-id="${o.id}">${o.archived?'Restore':'Archive'}</button>`:''}</div></td></tr>`).join(''):'<tr><td colspan="5">No records found.</td></tr>'}</tbody></table></div>`;
 }
 if(state.manageTab==='revisions'){
 const rows=state.revisions.filter(r=>r.status==='PENDING');return `<div class="alert-banner">Only Admin can approve or reject proposed edits. Source-linked details must be checked before approval.</div><div class="ui-grid two">${rows.length?rows.map(r=>`<section class="soft-panel"><div class="card-op-top">${statusChip('Pending change','warn')}<span class="muted small">${fmtDate(r.created_at)}</span></div><h3>${escapeHTML(opp(r.opportunity_id)?.title||'Existing opportunity')}</h3><p class="muted small">Suggested change to ${Object.keys(r.proposed_patch||{}).length} fields</p><button class="btn sm soft" data-action="revision" data-id="${r.id}">${roleAtLeast('admin')?'Review change':'View proposal'}</button></section>`).join(''):'<div class="empty">No pending edits.</div>'}</div>`;
 }
 if(state.manageTab==='assistance')return `<div class="ui-grid two">${state.requests.length?state.requests.map(r=>`<section class="soft-panel"><div class="card-op-top">${statusChip(r.status,r.status==='RESOLVED'?'good':'warn')}<span class="muted small">${fmtDate(r.created_at)}</span></div><h3>${escapeHTML(opp(r.opportunity_id)?.title||'Opportunity')}</h3><p class="muted small">${escapeHTML(r.requester_name)} · ${escapeHTML(r.requester_email)}</p><p class="small">${escapeHTML(r.help_type)} — ${escapeHTML(clip(r.message,140))}</p><button class="btn sm soft" data-action="respond" data-id="${r.id}">Respond / update</button></section>`).join(''):'<div class="empty">No assistance requests yet.</div>'}</div>`;
 if(state.manageTab==='reports')return `<div class="ui-grid two">${state.reports.length?state.reports.map(r=>`<section class="soft-panel"><div class="card-op-top">${statusChip(r.status,r.status==='REVIEWED'?'good':'warn')}</div><h3>${escapeHTML(r.issue_type)}</h3><p class="muted small">${escapeHTML(opp(r.opportunity_id)?.title||'Opportunity')}</p><p class="small">${escapeHTML(r.description)}</p>${r.status==='OPEN'?`<button class="btn sm soft" data-action="report-reviewed" data-id="${r.id}">Mark reviewed</button>`:''}</section>`).join(''):'<div class="empty">No reports yet.</div>'}</div>`;
 if(state.manageTab==='feedback')return `<div class="ui-grid two">${state.feedback.length?state.feedback.map(f=>`<section class="soft-panel"><div class="card-op-top">${statusChip(f.topic)}<span class="muted small">${fmtDate(f.created_at)}</span></div><p class="small">${escapeHTML(f.message)}</p></section>`).join(''):'<div class="empty">No website feedback yet.</div>'}</div>`;
 return '';
}
function renderSettings(){if(!roleAtLeast('admin'))return '';return heading('ADMIN CONTROLS','Settings & users ⚙️','Manage access and review the methodology. Changes should follow faculty consultation.')+
 `<div class="chart-duo"><section class="soft-panel"><h3>Assessment methodology</h3><p class="muted small">Five criteria; preset weights total 100%. Staff choose documented evidence categories, not numeric ratings.</p><form id="weights-form"><div class="form-two">${NEU_CRITERIA.map(k=>field(k,({benefit:'Potential benefit',feasibility:'Feasibility',relevance:'Strategic relevance',risk:'Risk',difficulty:'Difficulty'}[k])+' (%)',state.settings.weights[k],'number',true,'min="0" max="100"')).join('')}${field('high_threshold','High priority from',state.settings.high_threshold,'number',true,'min="1" max="100"')}${field('medium_threshold','Medium priority from',state.settings.medium_threshold,'number',true,'min="0" max="99"')}</div><button class="btn sm primary" type="submit">Save settings</button></form></section><section class="soft-panel"><h3>Account management</h3><p class="muted small">Create accounts in Supabase → Authentication → Users. Assign Staff/Admin roles here.</p>${state.users.map(u=>`<div class="legend-item" style="padding:9px 0;border-bottom:1px solid #ececf3"><span class="legend-name"><b>${escapeHTML(u.display_name||u.email)}</b><small class="muted">${escapeHTML(u.role)} · ${u.active?'Active':'Disabled'}</small></span><span class="table-actions"><button class="btn sm soft" data-action="change-role" data-id="${u.id}">Role</button><button class="btn sm light" data-action="toggle-user" data-id="${u.id}">${u.active?'Disable':'Enable'}</button></span></div>`).join('')}</section></div><div class="section-heading"><h2>Admin activity log</h2></div><section class="soft-panel"><div class="rank-list">${state.activity.length?state.activity.slice(0,30).map(x=>`<div class="legend-item"><span><b>${escapeHTML(x.action)}</b><span class="muted small"> · ${escapeHTML(x.entity)} · ${escapeHTML(clip(x.details,50))}</span></span><span class="muted small">${fmtDate(x.created_at)}</span></div>`).join(''):'<p class="muted small">No recent recorded changes.</p>'}</div></section>`;}
function renderProfile(){if(!state.me)return '';const me=state.me;return heading('MY ACCOUNT','My profile ♡','Keep your basic information up to date. Your role and email are managed securely.')+
 `<div class="ui-grid two"><section class="soft-panel"><h3>Personal information</h3><p class="muted small">Used to identify your requests for opportunity guidance.</p><form id="profile-form"><div class="form-two">${field('display_name','Full name',me.display_name,'text',true,'maxlength="120"')}${field('college','College / Department',me.college||'','text',true,'maxlength="120"')}${select('year_level','Year level',GOID_YEARS,me.year_level||'1st Year',true)}${field('contact_number','Phone (optional)',me.contact_number||'','tel',false,'maxlength="30"')}${field('telegram_username','Telegram (optional)',me.telegram_username||'','text',false,'maxlength="50"')}${select('preferred_contact','Preferred contact method',['Email','Telegram','Phone'],me.preferred_contact||'Email',true)}</div><p class="muted small">Registered email: <b>${escapeHTML(me.email)}</b> · Assigned access: ${escapeHTML(me.role)}. Update your email through account support if necessary.</p><button class="btn primary" type="submit">Save profile</button></form></section><section class="soft-panel"><h3>Privacy & account security</h3><p class="muted small">Only authorized team members handling assistance requests can view related contact information. Never include IDs, private documents, or passwords in messages.</p><button class="btn soft" type="button" data-action="privacy">Read privacy notice</button><p class="muted small" style="margin-top:14px">Verification confirms you control your email address; it does not verify enrollment or university endorsement.</p></section></div>`;}
function showPrivacy(){showModal(`${modalHeader('Privacy notice','Student research prototype — GOID')}
 <p class="small">We collect your name, email address, college/department, and year level to manage GOID accounts. Optional phone and Telegram details are used only if you request guidance and choose those channels.</p><p class="small">Your information is stored in the project Supabase database. Authorized Staff/Admin handling assistance requests may view relevant contact details; Students cannot view other students’ profiles. You may update your profile from My Profile and ask the project team for correction or deletion procedures.</p><p class="small">This is an academic prototype, not an official NEU service. Please do not upload government IDs, sensitive documents, or passwords. The project team should define retention and deletion procedures and complete a privacy review before wider use.</p><button class="btn soft" data-action="close-modal">Close</button>`);}
function renderFeedback(){return heading('HELP US IMPROVE','Website feedback ✧','Suggest website improvements. Feedback never changes opportunity rankings.')+`<section class="soft-panel" style="max-width:670px"><form id="feedback-form">${select('topic','What is your feedback about?',['Navigation','Clarity','Accessibility','Suggestion','Other'],'Suggestion',true)}${area('message','Your suggestion','',true)}<button class="btn primary" type="submit">Send feedback</button></form></section>`;}
function details(id){const o=opp(id);if(!o)return;const a=o.assessment||{},lines=a.lines||[],closed=/CLOSED/i.test(o.application_status||'')||deadlineState(o)==='expired';
 const checks=lines.map(l=>`<div class="evidence-row"><div><b>${escapeHTML(l.label)}</b><br><span>${escapeHTML(l.description)}</span></div><div style="text-align:right"><b>${l.rating?`${l.rating}/5`:'Missing'}</b><br>${neuLink(l.source_url)?`<a href="${escapeHTML(l.source_url)}" target="_blank" rel="noopener noreferrer">Evidence source ↗</a>`:''}</div></div>`).join('');
 const officialLink=neuLink(o.source_url)?`<a class="btn primary" target="_blank" rel="noopener noreferrer" href="${escapeHTML(o.source_url)}">↗ Official source</a>`:'';
 const contactLink=neuLink(o.contact_url)?`<a class="btn soft" target="_blank" rel="noopener noreferrer" href="${escapeHTML(o.contact_url)}">✉ Contact organization</a>`:'';
 const applyLink=!closed&&neuLink(o.application_url)?`<a class="btn soft" target="_blank" rel="noopener noreferrer" href="${escapeHTML(o.application_url)}">↗ Application portal</a>`:'';
 showModal(`<div class="compact-detail">${modalHeader(o.title)}<div class="detail-header">${categoryTag(o.sector)}${appChip(o)}${statusChip('Source reviewed','good')}</div><p class="muted small" style="margin:12px 0 15px">📍 ${escapeHTML(locationLabel(o))} · ${escapeHTML(o.stakeholder||'All interested users')}</p><p class="detail-about">${escapeHTML(clip(o.description,550)||'Please review the official source for details.')}</p><div class="detail-grid" style="margin:17px 0"><div class="detail-item"><b>Eligibility</b><p>${escapeHTML(clip(o.eligibility,170)||'Check the official requirements')}</p></div><div class="detail-item"><b>Funding / benefits</b><p>${escapeHTML(clip(o.funding,170)||'Not specified')}</p></div><div class="detail-item"><b>Application deadline</b><p>${fmtDate(o.deadline)}</p></div><div class="detail-item"><b>Last source review</b><p>${fmtDate(o.last_verified)}</p></div><div class="detail-item"><b>Source organization</b><p>${escapeHTML(o.source_org||'Not specified')}</p></div><div class="detail-item"><b>Assessment</b><p>${scoreLabel(o)} · ${o.score===null?'Evidence incomplete':escapeHTML(o.priority)+' priority'}</p></div><div class="detail-item"><b>Project decision status</b><p>${escapeHTML(o.decision||'Investigate further')}</p></div></div>
 <div class="assessment-note">${o.score===null?'Assessment is incomplete. The dashboard does not invent scores when evidence is missing.':'Scores reflect published evidence interpreted using a preset project rubric, not an official university endorsement.'}</div>
 <details class="details-why"><summary>How was this assessed?</summary><div style="margin-top:9px">${checks}</div><p class="muted small">Each documented criterion is assigned a fixed rubric value; weighted contributions sum to 100 points. Category judgments are still preliminary research interpretations and should be validated by faculty.</p></details>
 <div class="detail-actions">${officialLink}${applyLink}${contactLink}<button class="btn light" data-action="compare-add" data-id="${o.id}">⇄ Compare</button>${roleAtLeast('student')?`<button class="btn soft" data-action="request" data-id="${o.id}">✉ Request assistance</button><button class="btn light" data-action="bookmark" data-id="${o.id}">${saved(o.id)?'♥ Saved':'♡ Save'}</button><button class="btn light" data-action="report" data-id="${o.id}">⚑ Report an issue</button>`:`<button class="btn soft" data-action="show-login">Sign in for assistance</button>`}</div><p class="muted small">The assistance workflow is a student project proposal; program acceptance or university support is not guaranteed.</p></div>`,false);
}
function evidenceFields(data={}){return NEU_CRITERIA.map(k=>{
 const current=(data?.evidence||{})[k]||{};
 const name={benefit:'Potential benefit',feasibility:'Feasibility',relevance:'Strategic relevance',risk:'Risk / safeguards',difficulty:'Estimated difficulty'}[k];
 return `<div class="soft-panel" style="padding:13px;margin-bottom:10px;background:#fbfbfe"><div class="form-two"><div class="form-input"><label for="e-${k}">${escapeHTML(name)}</label><select name="e_${k}" id="e-${k}"><option value="">Insufficient evidence — not assessed</option>${NEU_RUBRIC[k].map(([code,label])=>`<option value="${code}" ${current.code===code?'selected':''}>${escapeHTML(label)}</option>`).join('')}</select></div>${field('url_'+k,'Official evidence link',current.source_url||'','url',false,'placeholder="https://…"')}</div></div>`;
 }).join('');}
function editOpportunity(id){if(!roleAtLeast('staff'))return;const o=id?opp(id):null;
 const r=o||{title:'',country:'Philippines',region:'National Capital Region (NCR)',sector:CATEGORIES[0].id,stakeholder:'Students',description:'',eligibility:'',funding:'',deadline:'',requirements:'',risks:'',source_org:'',source_url:'',application_url:'',contact_url:'',application_status:'CHECK CURRENT INTAKE',evidence:{}};
 const isProposal=!!(o&&o.verification==='VERIFIED'&&!roleAtLeast('admin'));
 showModal(`${modalHeader(o?(isProposal?'Propose an edit':'Edit opportunity'):'Add opportunity',isProposal?'Published information stays unchanged until Admin approves your proposal.':'Official source links are required for all new records.')}
 <form id="record-form" data-id="${o?.id||''}"><div class="form-two">${field('title','Opportunity title',r.title,'text',true)}${select('sector','Category',CATEGORIES.map(c=>[c.id,c.short]),r.sector,true)}${select('country','Country',COUNTRIES,r.country,true)}${select('region','Philippine region',[['','Select a region'],...PH_REGIONS],r.region)}${select('stakeholder','Intended users',STAKEHOLDERS,r.stakeholder)}${select('application_status','Application status',STATUS_OPTIONS,r.application_status)}${field('source_org','Official source organization',r.source_org,'text',true)}${field('source_url','Official source URL (https)',r.source_url,'url',true)}${field('application_url','Application portal (optional)',r.application_url,'url')}${field('contact_url','Official contact page (optional)',r.contact_url||'','url')}${field('deadline','Deadline (if published)',r.deadline,'date')}${roleAtLeast('admin')?select('decision','Project decision status',['INVESTIGATE FURTHER','MONITOR','PURSUE','REJECT'],r.decision||'INVESTIGATE FURTHER'):''}${area('description','Short description',r.description)}${area('eligibility','Eligibility summary',r.eligibility)}${area('funding','Funding / benefits',r.funding)}${area('requirements','Key requirements (optional)',r.requirements)}${area('risks','Documented risks (optional)',r.risks)}</div>
 <div class="section-heading"><h2>Evidence-based assessment</h2></div><div class="alert-banner purple">Choose only what the official evidence supports. Leave a criterion blank when information is uncertain. The website calculates the score automatically; Staff cannot type a personal numerical rating.</div>${evidenceFields(r)}<div id="score-preview" class="assessment-note">Assessment preview updates as you fill in the evidence.</div><div class="footer-buttons"><button type="button" class="btn light" data-action="close-modal">Cancel</button><button type="submit" class="btn primary">${isProposal?'Submit for Admin review':o?'Save changes':'Submit opportunity'}</button></div></form>`,true);
 updateEvidencePreview();
}
function collectRecord(form){const data=Object.fromEntries(new FormData(form).entries()),evidence={};
 for(const k of NEU_CRITERIA){const code=data['e_'+k],source_url=(data['url_'+k]||'').trim();if(code){if(!source_url)throw Error(`Add an evidence link for ${k}, or leave the criterion unassessed.`);evidence[k]={code,source_url};}delete data['e_'+k];delete data['url_'+k];}
 data.evidence=evidence;if(data.country!=='Philippines')data.region='';if(data.country==='Philippines'&&!data.region)throw Error('Please choose the Philippine region (or Nationwide).');
 if(!neuLink(data.source_url))throw Error('Enter a valid HTTPS official source URL.');return data;
}
function updateEvidencePreview(){const form=$('#record-form');if(!form)return;try{
 const d=Object.fromEntries(new FormData(form).entries()),evidence={};for(const k of NEU_CRITERIA){if(d['e_'+k]&&neuLink(d['url_'+k]))evidence[k]={code:d['e_'+k],source_url:d['url_'+k]};}
 const score=neuScore({evidence},state.settings);$('#score-preview').innerHTML=score.score===null?`<b>Not assessed yet</b> · ${score.assessment.missing.length} of 5 criteria still need supported evidence.`:`<b>Rubric preview:</b> ${score.score.toFixed(1)}/100 · ${score.priority} priority. This is not an official rating.`;
 }catch(e){$('#score-preview').textContent=e.message;}}
function approve(id){const o=opp(id);if(!o||!roleAtLeast('admin'))return;showModal(`${modalHeader('Review new opportunity','Confirm the organization and official source before publication.')}
 <div class="soft-panel"><b>${escapeHTML(o.title)}</b><p class="muted small" style="margin:7px 0">${escapeHTML(locationLabel(o))} · ${escapeHTML(o.source_org||'Missing organization')}</p>${neuLink(o.source_url)?`<a class="link-plain" href="${escapeHTML(o.source_url)}" target="_blank" rel="noopener noreferrer">View source ↗</a>`:'<p class="muted">No valid source link — edit this record first.</p>'}</div>
 <div class="alert-banner">Approval requires an HTTPS source URL, source organization, reviewer name and, for Philippine opportunities, a region. The listing will appear publicly only after approval succeeds.</div>
 <form id="approve-form" data-id="${id}">${field('reviewer','Name of reviewer','','text',true)}<div class="footer-buttons"><button type="button" class="btn light" data-action="close-modal">Cancel</button><button type="button" class="btn soft" data-action="edit" data-id="${id}">Edit record</button><button class="btn primary" type="submit">Approve & publish</button></div></form>`);}
function reviewRevision(id){const r=state.revisions.find(x=>x.id===id);if(!r)return;const o=opp(r.opportunity_id),changes=r.proposed_patch||{};
 showModal(`${modalHeader('Review proposed changes','Check every proposed field against the official source.')}
 <h3>${escapeHTML(o?.title||'Opportunity')}</h3><div class="soft-panel" style="max-height:220px;overflow:auto">${Object.entries(changes).map(([k,v])=>`<div class="evidence-row"><b>${escapeHTML(k.replaceAll('_',' '))}</b><span style="max-width:65%;overflow-wrap:anywhere">${escapeHTML(typeof v==='object'?JSON.stringify(v):String(v??''))}</span></div>`).join('')}</div>
 ${roleAtLeast('admin')?`<form id="review-form" data-id="${id}">${field('reviewer','Reviewer name','','text',true)}${area('note','Review notes (optional)','')}<div class="footer-buttons"><button type="button" class="btn light" data-action="close-modal">Cancel</button><button type="button" class="btn danger" data-action="revision-reject" data-id="${id}">Reject</button><button type="submit" class="btn primary">Approve change</button></div></form>`:'<p class="muted small">Only Admin can approve this change.</p>'}`);
}
function assistanceForm(id){if(!roleAtLeast('student'))return needLogin();const o=opp(id);if(!o)return;
 showModal(`${modalHeader('Request assistance','Ask for guidance about this opportunity — not a formal application.')}
 <div class="alert-banner purple"><b>${escapeHTML(o.title)}</b><br>Requests go to authorized project Staff, subject to an agreed university assistance process. Please do not submit sensitive documents or ID numbers.</div>
 <form id="assistance-form" data-id="${id}">${field('requester_name','Your name',state.me.display_name||'','text',true)}${field('requester_email','Contact email',state.me.email||'','email',true)}${select('help_type','What do you need help with?',['Eligibility','Requirements','Application process','Other'],'Eligibility',true)}${area('message','Question (optional)','')}<div class="footer-buttons"><button type="button" class="btn light" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Submit request</button></div></form>`);
}
async function respond(id){const r=state.requests.find(x=>x.id===id);if(!r)return;const contact=await neuApi('/api/assistance/'+id+'/contact');
 showModal(`${modalHeader('Assistance request','Use only official project communication channels for responses.')}
 <div class="soft-panel"><b>${escapeHTML(r.requester_name)}</b><p class="muted small">${escapeHTML(contact.email||r.requester_email)} · ${escapeHTML(contact.college||'College not given')} · ${escapeHTML(contact.year_level||'Year not given')} · ${escapeHTML(r.help_type)}</p><p class="small">Preferred contact: ${escapeHTML(contact.preferred_contact||'Email')} ${contact.contact_number?` · Phone: ${escapeHTML(contact.contact_number)}`:''} ${contact.telegram_username?` · Telegram: ${escapeHTML(contact.telegram_username)}`:''}</p><p style="white-space:pre-wrap">${escapeHTML(r.message||'No message provided')}</p></div>
 <form id="respond-form" data-id="${id}">${select('status','Request status',['NEW','IN PROGRESS','RESOLVED'],r.status,true)}${area('staff_reply','Guidance / response',r.staff_reply)}<div class="footer-buttons"><button type="button" class="btn light" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Save response</button></div></form>`);
}
function reportForm(id){if(!roleAtLeast('student'))return needLogin();showModal(`${modalHeader('Report incorrect information','Please identify which details may need another source check.')}
 <form id="report-form" data-id="${id}">${select('issue_type','Issue type',['Outdated deadline','Broken link','Incorrect details','Other'],'Outdated deadline',true)}${area('description','What needs checking?','',true)}<div class="footer-buttons"><button type="button" class="btn light" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Send report</button></div></form>`);}
function guide(){showModal(`${modalHeader('Quick guide','Sign in to explore opportunities and use GOID features.')}
 <div class="rank-list"><div class="rank-item">🌏 <div class="rank-main"><b>Discover</b><small>Explore four categories across the Philippines and five selected Asian markets.</small></div></div><div class="rank-item">⚖️ <div class="rank-main"><b>Understand the assessment</b><small>Review evidence and criteria. Missing evidence means Not assessed.</small></div></div><div class="rank-item">♡ <div class="rank-main"><b>Save & request assistance</b><small>Bookmark listings or ask project Staff for guidance using your account.</small></div></div><div class="rank-item">✅ <div class="rank-main"><b>Review before publication</b><small>Staff submissions and edits to published listings require Admin approval.</small></div></div></div><p class="muted small" style="margin-top:14px">This is a student research prototype; no guarantee of eligibility, admission, funding, or official NEU endorsement.</p>`);}
function roleForm(id){const u=state.users.find(x=>x.id===id);if(!u)return;showModal(`${modalHeader('Change user role',u.email)}<form id="role-form" data-id="${id}">${select('role','Access level',[['student','Student (read only)'],['staff','Staff (submit records)'],['admin','Admin (approve & manage)']],u.role,true)}<div class="footer-buttons"><button type="button" class="btn light" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Save role</button></div></form>`);}
async function mutation(path,method,payload,success){const result=await neuApi(path,method,payload);closeModal();await boot(true);toast(success);return result;}

document.addEventListener('click',async e=>{
 const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action,id=el.dataset.id;
 try{
 if(action==='nav'){navigate(el.dataset.page);return;}
 if(action==='toggle-menu'){$('#sidebar').classList.toggle('open');return;}
 if(action==='show-login'){showLogin();return;}
  if(action==='auth-login'){showLogin('login');return;}
  if(action==='auth-signup'){showLogin('signup');return;}
  if(action==='auth-forgot'){showLogin('forgot');return;}
  if(action==='privacy'){e.preventDefault();showPrivacy();return;}

 if(action==='logout'){await neuApi('/api/logout','POST');await boot();toast('You have signed out.');return;}
 if(action==='close-modal'){closeModal();return;}
 if(action==='guide'){guide();return;}
 if(action==='category'){state.tab=el.dataset.sector;render();return;}
 if(action==='detail'){details(id);return;}
 if(action==='bookmark'){if(!roleAtLeast('student'))return needLogin();await mutation('/api/bookmarks/'+id,saved(id)?'DELETE':'POST',{},saved(id)?'Removed from saved opportunities.':'Saved to your account.');return;}
 if(action==='request'){assistanceForm(id);return;}
 if(action==='report'){reportForm(id);return;}
 if(action==='compare-add'){if(state.compare.length>=3)throw Error('Compare up to three opportunities.');if(!state.compare.includes(id))state.compare.push(id);toast('Added to comparison list.');return;}
 if(action==='compare-remove'){state.compare=state.compare.filter(x=>x!==id);render();return;}
 if(action==='clear-compare'){state.compare=[];render();return;}
 if(action==='add'){editOpportunity();return;}
 if(action==='edit'){editOpportunity(id);return;}
 if(action==='approve'){approve(id);return;}
 if(action==='manage-tab'){state.manageTab=el.dataset.tab;render();return;}
 if(action==='revision'){reviewRevision(id);return;}
 if(action==='revision-reject'){
  const f=$('#review-form');if(!confirm('Reject this pending edit? The published record will stay unchanged.'))return;
  await mutation('/api/revisions/'+id+'/review','POST',{approve:false,reviewer:f?.elements.reviewer.value||'',note:f?.elements.note.value||''},'Proposed edit rejected.');return;
 }
 if(action==='respond'){respond(id);return;}
 if(action==='report-reviewed'){await mutation('/api/reports/'+id,'PATCH',{status:'REVIEWED'},'Issue marked reviewed.');return;}
 if(action==='change-role'){roleForm(id);return;}
 if(action==='archive'){
  if(!roleAtLeast('admin'))throw Error('Admin-only action.');if(!confirm('Archive this opportunity? It will no longer appear to visitors.'))return;
  await mutation('/api/opportunities/'+id,'PATCH',{archived:true,verification:'ARCHIVED'},'Record archived.');return;
 }
 if(action==='export'){neuDownloadExport('json',state.opportunities);return;}
 if(action==='export-csv'){neuDownloadExport('csv',state.opportunities);return;}
 if(action==='show-archived'){state.includeArchived=!state.includeArchived;render();return;}
 if(action==='toggle-user'){const u=state.users.find(x=>x.id===id);if(!u)return;if(!confirm((u.active?'Disable ':'Enable ')+u.email+'?'))return;await mutation('/api/users/'+id,'PATCH',{active:!u.active},'Account access updated.');return;}
 if(action==='restore'){if(!roleAtLeast('admin'))throw Error('Admin-only action.');if(!confirm('Restore as pending for re-verification?'))return;await mutation('/api/opportunities/'+id,'PATCH',{archived:false,verification:'PENDING VERIFICATION'},'Record restored to pending review.');return;}
 if(action==='import'){$('#import-input').click();return;}
 }catch(err){toast(err.message,true);}
});
document.addEventListener('input',e=>{
 if(e.target.id==='query'){state.query=e.target.value;updateExplore();return;}
 if(e.target.id==='manage-query'){state.manageQuery=e.target.value;const table=$('#manage-content');if(table){const pos=e.target.selectionStart;table.innerHTML=renderManageTab();const input=$('#manage-query');input.focus();input.setSelectionRange(pos,pos);}return;}
 if(e.target.closest('#record-form')&&(e.target.name?.startsWith('e_')||e.target.name?.startsWith('url_')))updateEvidencePreview();
});
document.addEventListener('change',e=>{
 if(e.target.id==='country'){state.country=e.target.value;state.region='';render();return;}
 if(e.target.id==='region'){state.region=e.target.value;updateExplore();return;}
 if(e.target.id==='sort'){state.sort=e.target.value;updateExplore();return;}
 if(e.target.id==='compare-add'&&e.target.value){if(state.compare.length>=3)return toast('Up to three opportunities only.',true);if(!state.compare.includes(e.target.value))state.compare.push(e.target.value);render();return;}
 if(e.target.closest('#record-form')&&(e.target.name?.startsWith('e_')||e.target.name?.startsWith('url_')))updateEvidencePreview();
});
document.addEventListener('submit',async e=>{
 const f=e.target,valid=['signup-form','resend-form','forgot-form','new-password-form','profile-form','login-form','record-form','approve-form','review-form','assistance-form','respond-form','report-form','feedback-form','weights-form','role-form'];if(!valid.includes(f.id))return;
 e.preventDefault();const btn=f.querySelector('[type=submit]');if(btn)btn.disabled=true;
 try{
 const d=Object.fromEntries(new FormData(f).entries());
  if(f.id==='login-form'){await neuApi('/api/login','POST',d);await boot();toast('Welcome to GOID! ✨');}
  else if(f.id==='signup-form'){
    if(d.password!==d.confirm_password)throw Error('Your passwords do not match.');
    if(!d.privacy_acknowledged)throw Error('Please read the privacy notice.');
    await neuApi('/api/signup','POST',{...d,privacy_acknowledged:true});state.pendingEmail=d.email;showLogin('verify');toast('Check your email for the confirmation link.');
  }
  else if(f.id==='resend-form'){await neuApi('/api/resend-confirmation','POST',d);state.pendingEmail=d.email;toast('If eligible, another verification email has been requested.');}
  else if(f.id==='forgot-form'){await neuApi('/api/forgot-password','POST',d);state.pendingEmail=d.email;showLogin('reset-sent');toast('If the email exists, a password reset link has been requested.');}
  else if(f.id==='new-password-form'){
    if(d.password!==d.confirm_password)throw Error('Your passwords do not match.');
    await neuApi('/api/new-password','POST',d);state.authRecovery=false;showLogin('login');toast('Password updated. Sign in again.');
  }
  else if(f.id==='profile-form'){await mutation('/api/my-profile','PATCH',d,'Profile updated successfully.');}

 else if(f.id==='record-form'){
  const record=collectRecord(f),id=f.dataset.id;
  const result=await mutation(id?'/api/opportunities/'+id:'/api/opportunities',id?'PATCH':'POST',record,id?'Changes submitted.':'Opportunity submitted for review.');
  if(result.pending_revision)toast('Proposed edit saved for Admin review. The original public listing is unchanged.');
 }
 else if(f.id==='approve-form'){await mutation('/api/opportunities/'+f.dataset.id+'/approve','POST',{reviewer:d.reviewer},'Source reviewed and opportunity published.');}
 else if(f.id==='review-form'){await mutation('/api/revisions/'+f.dataset.id+'/review','POST',{approve:true,reviewer:d.reviewer,note:d.note},'Proposed edit approved and published.');}
 else if(f.id==='assistance-form'){await mutation('/api/assistance','POST',{...d,opportunity_id:f.dataset.id},'Request submitted. Follow its status under My assistance.');}
 else if(f.id==='respond-form'){await mutation('/api/assistance/'+f.dataset.id,'PATCH',d,'Response saved.');}
 else if(f.id==='report-form'){await mutation('/api/reports','POST',{...d,opportunity_id:f.dataset.id},'Thank you. The team will review the report.');}
 else if(f.id==='feedback-form'){await mutation('/api/feedback','POST',d,'Feedback submitted. Thank you!');}
 else if(f.id==='weights-form'){
  const weights={};for(const k of NEU_CRITERIA)weights[k]=Number(d[k]);await mutation('/api/settings','PATCH',{weights,high_threshold:Number(d.high_threshold),medium_threshold:Number(d.medium_threshold)},'Assessment settings updated.');
 }
 else if(f.id==='role-form'){await mutation('/api/users/'+f.dataset.id,'PATCH',{role:d.role},'User role updated.');}
 }catch(err){toast(err.message,true);}finally{if(btn&&btn.isConnected)btn.disabled=false;}
});

$('#import-input').addEventListener('change',async e=>{
 const f=e.target.files[0];if(!f)return;
 try{const data=JSON.parse(await f.text());if(!Array.isArray(data.opportunities))throw Error('Choose a JSON export containing opportunities.');
  if(!confirm(`Import ${data.opportunities.length} items as PENDING? Existing approved records will not be overwritten.`))return;
  const r=await neuApi('/api/import','POST',{opportunities:data.opportunities});await boot(true);toast(`${r.count} pending submissions imported; ${r.skipped} skipped.`);
 }catch(err){toast(err.message,true);}finally{e.target.value='';}
});
const originalRender=render;
render=function(){originalRender();if(state.page==='explore')updateExplore();};
if(!neuConfigured()){
 showLogin();$('#config-status').textContent='Website setup is incomplete: keep your existing working config.js, or follow the upgrade guide to connect Supabase.';
}else{
 neuGetClient().auth.onAuthStateChange((event)=>{if(event==='PASSWORD_RECOVERY'){state.authRecovery=true;showLogin('new-password');}});
 boot().then(()=>{try{neuActivateRealtime(()=>{if(!state.working&&$('#modal').classList.contains('hidden'))boot(true);});}catch(e){console.warn('Realtime:',e.message);}});
}
